def copy_listing_prices_to_skus(apps, schema_editor):
    """Every existing listing keeps its price, discount and stock as one
    default SKU (no variants) before those columns are dropped."""
    Listing = apps.get_model("catalog", "Listing")
    ListingSku = apps.get_model("catalog", "ListingSku")
    skus = [
        ListingSku(
            listing_id=row.id,
            price=row.price,
            discounted_price=row.discounted_price if row.discounted_price is not None else row.price,
            stock_qty=row.stock_qty,
            reserved_qty=row.reserved_qty or 0,
            is_active=True,
            creator_type="system",
        )
        for row in Listing._base_manager.all()
    ]
    ListingSku.objects.bulk_create(skus)


